param([Parameter(Mandatory=$true)][string]$EvidencePath)
$ErrorActionPreference='Stop';$e=Get-Content -LiteralPath (Resolve-Path -LiteralPath $EvidencePath) -Raw|ConvertFrom-Json
if($e.schema_version-ne1-or$e.artifact_type-ne'r15_wmi_free_launch_test_evidence'-or$e.status-ne'pass'-or$e.pilot_launched-ne$false-or$e.production_markers_created-ne$false-or$e.run_id_prefix-ne'paper-text-v1-multiseed-cap128-r15-20260831'){throw 'r15 launch evidence identity/status failed'}
if($e.scheduler_canary.status-ne'pass'-or$e.scheduler_canary.actual_staged_supervisor-ne$true-or$e.scheduler_canary.wmi_used-ne$false-or$e.scheduler_canary.native_parent-ne$true-or$e.scheduler_canary.native_power-ne$true-or$e.scheduler_canary.native_storage-ne$true-or[double]$e.scheduler_canary.elapsed_seconds-ge30){throw 'r15 scheduler canary evidence failed'}
if($e.foreground_wrapper.status-ne'pass'-or[int]$e.foreground_wrapper.windows_host_exit_code-ne17-or[int]$e.foreground_wrapper.atomic_exit_code-ne17-or$e.foreground_wrapper.production_markers_created-ne$false){throw 'r15 wrapper evidence failed'}
if([int]$e.unit_tests.host.tests-ne10-or[int]$e.unit_tests.locked_wsl_tf24.tests-ne10-or[int]$e.import_closure.reachable_repository_modules-ne18-or$e.import_closure.host_wsl_paths_identical-ne$true){throw 'r15 regression/import evidence failed'}
$seen=@{};foreach($b in @($e.source_bindings)){if($seen.ContainsKey([string]$b.name)){throw 'duplicate source binding'};$p=(Resolve-Path -LiteralPath ([string]$b.path)).Path;$sha=(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant();if($sha-ne[string]$b.sha256){throw "source changed: $($b.name)"};$seen[[string]$b.name]=$true};if($seen.Count-lt45){throw 'r15 source binding closure is unexpectedly small'}
[ordered]@{status='pass';pilot_launched=$false;source_bindings=$seen.Count;actual_supervisor_canary=$true;native_preflight=$true;wrapper_atomic_exit=$true;host_tests=10;locked_tests=10;reachable_modules=18}|ConvertTo-Json -Compress
